<?php
namespace App\Console\Commands;
use App\Models\Order; use App\Models\Product; use App\Services\WalletService; use Illuminate\Console\Command; use Illuminate\Support\Facades\Cache;
class ProcessPickupDeadlines extends Command { protected $signature='savebite:process-pickups'; protected $description='Notify pickup deadline and refund expired tickets'; public function handle(WalletService $wallet): int { Order::with('user')->where('status','ready_for_pickup')->whereNull('pickup_warning_sent_at')->whereBetween('pickup_expires_at',[now(),now()->addMinutes(30)])->each(function($o){$o->user->notify(new \App\Notifications\PickupClosingNotification($o));$o->update(['pickup_warning_sent_at'=>now()]);}); Order::with(['user','product'])->where('status','ready_for_pickup')->where('pickup_expires_at','<=',now())->each(function($o) use($wallet){$wallet->credit($o->user,(int)$o->total_price,'refund-expired-'.$o->id,'Refund tiket kedaluwarsa '.$o->booking_code,$o);$o->product->increment('stock',$o->quantity);$o->update(['status'=>'expired_refunded','refunded_at'=>now()]);$o->user->notify(new \App\Notifications\RefundNotification($o));}); Product::with('merchant.user')->where('is_active',false)->whereNotNull('pickup_start_time')->each(function($p){$start=now($p->merchant->timezone ?: 'Asia/Jakarta')->setTimeFromTimeString($p->pickup_start_time);$key='menu-reminder-'.$p->id.'-'.$start->toDateString();if($start->between(now($p->merchant->timezone)->addMinutes(30),now($p->merchant->timezone)->addHours(2)) && Cache::add($key,true,$start->copy()->endOfDay())) $p->merchant->user?->notify(new \App\Notifications\MenuActivationReminder($p));}); return self::SUCCESS; } }
